SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, MONTH(BULAN) m, ROUND(SUM(IFF(UPPER(MATURITY_STATUS) LIKE 'TM%' AND KATEGORI_TANAH='PLANTED',HEKTAR,0)),2) ha FROM PRD_DB_INTEGRATION.INT_PANEN.INT_HEKTAR_BLOK WHERE KODE_BA IN ('2121','2124','2131','2122') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1,2,3 HAVING SUM(IFF(UPPER(MATURITY_STATUS) LIKE 'TM%' AND KATEGORI_TANAH='PLANTED',HEKTAR,0))>0 ORDER BY 1,2,3